const body = $json.body || $json;

const pain = String(body.pain || '').trim();
const manifestations = String(body.manifestations || '').trim();
const impact = String(body.impact || '').trim();
const desired = String(body.desired || '').trim();

if (!pain && !manifestations && !impact && !desired) {
  throw new Error('Не заполнены данные консультации');
}

const instructions = `Ты помогаешь специалисту сформулировать рабочий терапевтический запрос из слов клиента. Не ставь диагнозы. Не придумывай травмы, причины, события или убеждения, которых клиент не называл. Не утверждай скрытые причины как факты. Главный запрос формулируй от первого лица через «Хочу…» и описывай желаемое изменение, а не ярлык проблемы. Если информации недостаточно, прямо укажи, что нужно уточнить. Отвечай только валидным JSON без markdown и без пояснений вокруг JSON.`;

const prompt = `Данные бесплатной консультации:

БОЛЬ КЛИЕНТА:
${pain || 'Не указано'}

ГДЕ ПРОЯВЛЯЕТСЯ:
${manifestations || 'Не указано'}

КАК МЕШАЕТ ЖИТЬ:
${impact || 'Не указано'}

ЧЕГО ХОЧЕТ ВМЕСТО ЭТОГО:
${desired || 'Не указано'}

Верни JSON строго такой структуры:
{
  "mainRequest": "Короткий основной запрос от первого лица, начинающийся с Хочу",
  "analysis": "Кратко: главная трудность, повторяющийся сценарий и последствия — только то, что следует из слов клиента",
  "desiredResult": "Желаемый результат понятным языком",
  "clarifyingQuestion": "Один самый полезный уточняющий вопрос. Если всё достаточно ясно — Информации достаточно.",
  "alternatives": ["Вариант 1", "Вариант 2", "Вариант 3"]
}`;

return [{ json: {
  accessKey: String(body.accessKey || ''),
  clientId: String(body.clientId || ''),
  clientName: String(body.clientName || ''),
  instructions,
  prompt
} }];

const r = $json || {};
let text = String(r.output_text || '').trim();

if (!text && Array.isArray(r.output)) {
  for (const item of r.output) {
    if (!Array.isArray(item?.content)) continue;
    for (const part of item.content) {
      if (part?.type === 'output_text' && part?.text) {
        text += String(part.text);
      }
    }
  }
}

text = text.trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/i, '').trim();
if (!text) throw new Error('OpenAI не вернул текст');

let obj;
try {
  obj = JSON.parse(text);
} catch (e) {
  throw new Error('OpenAI вернул невалидный JSON: ' + text.slice(0, 300));
}

return [{ json: {
  mainRequest: String(obj.mainRequest || '').trim(),
  analysis: String(obj.analysis || '').trim(),
  desiredResult: String(obj.desiredResult || '').trim(),
  clarifyingQuestion: String(obj.clarifyingQuestion || '').trim(),
  alternatives: Array.isArray(obj.alternatives) ? obj.alternatives.map(x => String(x || '').trim()).filter(Boolean) : []
} }];
